-- Balance telemetry for staff (data/scripts/chaos/telemetry.lua, telemetry_core.lua; server/README.md "Balance
-- telemetry"; website page.php?plugin=chaos&p=telemetry). Aggregates only: no character id, name or account in any row.
-- span 'h': one row per UTC hour (`at` = the hour's start), kept telemetry_config.lua hourlyDays (90); then rolled up to
-- span 'd' (`at` = the day's start), kept dailyDays (730). A daily row's `players` is the sum of its hours
-- (character-hours). telemetry.lua creates the same tables at startup (ChaosTelemetryCore.schemaSql; the test compares).
-- Safe to run more than once.

CREATE TABLE IF NOT EXISTS `chaos_telemetry_hunt` (`span` char(1) NOT NULL, `at` int unsigned NOT NULL, `band` varchar(12) NOT NULL DEFAULT '', `voc` smallint NOT NULL DEFAULT 0, `players` bigint NOT NULL DEFAULT 0, `hunt_seconds` bigint NOT NULL DEFAULT 0, `exp` bigint NOT NULL DEFAULT 0, `loot` bigint NOT NULL DEFAULT 0, `supplies` bigint NOT NULL DEFAULT 0, `kills` bigint NOT NULL DEFAULT 0, PRIMARY KEY (`span`, `at`, `band`, `voc`), KEY `at` (`at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `chaos_telemetry_online` (`span` char(1) NOT NULL, `at` int unsigned NOT NULL, `band` varchar(12) NOT NULL DEFAULT '', `voc` smallint NOT NULL DEFAULT 0, `samples` bigint NOT NULL DEFAULT 0, `online_sum` bigint NOT NULL DEFAULT 0, `online_max` bigint NOT NULL DEFAULT 0, PRIMARY KEY (`span`, `at`, `band`, `voc`), KEY `at` (`at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `chaos_telemetry_boss` (`span` char(1) NOT NULL, `at` int unsigned NOT NULL, `boss` varchar(64) NOT NULL DEFAULT '', `party` tinyint NOT NULL DEFAULT 0, `kills` bigint NOT NULL DEFAULT 0, `timed` bigint NOT NULL DEFAULT 0, `secs_total` bigint NOT NULL DEFAULT 0, `secs_min` bigint NOT NULL DEFAULT 0, `secs_max` bigint NOT NULL DEFAULT 0, PRIMARY KEY (`span`, `at`, `boss`, `party`), KEY `at` (`at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `chaos_telemetry_deaths` (`span` char(1) NOT NULL, `at` int unsigned NOT NULL, `band` varchar(12) NOT NULL DEFAULT '', `area` varchar(64) NOT NULL DEFAULT '', `killer` varchar(64) NOT NULL DEFAULT '', `deaths` bigint NOT NULL DEFAULT 0, PRIMARY KEY (`span`, `at`, `band`, `area`, `killer`), KEY `at` (`at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `chaos_telemetry_casts` (`span` char(1) NOT NULL, `at` int unsigned NOT NULL, `voc` smallint NOT NULL DEFAULT 0, `spell` varchar(64) NOT NULL DEFAULT '', `casts` bigint NOT NULL DEFAULT 0, `players` bigint NOT NULL DEFAULT 0, PRIMARY KEY (`span`, `at`, `voc`, `spell`), KEY `at` (`at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `chaos_telemetry_economy` (`span` char(1) NOT NULL, `at` int unsigned NOT NULL, `flow` varchar(8) NOT NULL DEFAULT '', `source` varchar(32) NOT NULL DEFAULT '', `band` varchar(12) NOT NULL DEFAULT '', `gold` bigint NOT NULL DEFAULT 0, `events` bigint NOT NULL DEFAULT 0, PRIMARY KEY (`span`, `at`, `flow`, `source`, `band`), KEY `at` (`at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
